import yfinance as yf
import json

etfs = ['SPYM','SCHG','DYNF','CGGR','SPHQ','XLG','AIQ','SOXQ','PSI','TMFC','USMC','SNPE']
results = []

for sym in etfs:
    try:
        t = yf.Ticker(sym)
        info = t.info
        price = info.get('regularMarketPrice') or info.get('currentPrice') or 0
        vol = info.get('averageVolume') or 0
        iv = info.get('impliedVolatility') or info.get('volatility') or None
        # Try to get IV from options if not in info
        if iv is None:
            try:
                expires = list(t.options)
                if expires:
                    opt = t.option_chain(expires[0])
                    puts = opt.puts
                    puts['dist'] = abs(puts['strike'] - price)
                    atm = puts.loc[puts['dist'].idxmin()]
                    iv = atm['impliedVolatility'] * 100 if 'impliedVolatility' in atm else None
            except:
                pass
        results.append({
            'symbol': sym,
            'price': round(price, 2) if price else0,
            'volume': round(vol/1e6, 1) if vol else 0,
            'iv': round(iv, 1) if iv else None
        })
    except Exception as e:
        results.append({'symbol': sym, 'price': 0, 'volume': 0, 'iv': None, 'error': str(e)[:50]})

for r in results:
    iv_str = f"{r['iv']}%" if r['iv'] else "N/A"
    print(f"{r['symbol']:6s}  Price: ${r['price']:>8.2f}  Vol: {r['volume']:>5.1f}M  IV: {iv_str}")
EOF", "timeout": 120}
